print('=== UNIQUE WORKERS ===')
for w in sorted(all_workers):
    print(f'  {w}')

# Also get ALL experiments that have notes (for completeness)
print()
print('=== ALL EXPERIMENTS WITH NOTES ===')
for exp_id, exp_data in sorted(exps.items()):
